function(ctx) {
      const repo = repoById(ctx.id);
      const branch = ctx.data.branch;
      const f = ctx.form || {};
      const u = ui();
      const path = String(f.path || '');
      const message = String(f.message || '').trim();
      // A rejected submission keeps what was typed, so the reason can be read and corrected.
      u.fileDraft = { path: path, content: String(f.content || ''), message: String(f.message || '') };
      if (!path || path.startsWith('/') || path.split('/').indexOf('..') !== -1) { u.fileError = 'Invalid file path'; ARC.render(); return; }
      if (fileOn(repo, branch, path) || entriesOf(repo, branch, '').some((e) => e.name === path && e.type === 'dir')) { u.fileError = 'Invalid file path'; ARC.render(); return; }
      if (!message || message.length > 72) { u.fileError = 'Commit message is required'; ARC.render(); return; }
      list('files').push({ id: uid('f'), repoId: repo.id, branch: branch, path: path, content: String(f.content || '') });
      const b = branchList(repo).find((x) => x.name === branch);
      const cid = uid('c');
      const addedLines = String(f.content || '').split('\n').map((t) => ({ type: 'add', text: t }));
      list('commits').push({ id: cid, repoId: repo.id, branch: branch, seq: 99, message: message, author: (me() || {}).username || '', at: 'just now', parent: b ? b.commitId : null, additions: addedLines.length, deletions: 0, files: [{ path: path, additions: addedLines.length, deletions: 0, lines: addedLines }] });
      if (b) b.commitId = cid;
      u.fileError = '';
      u.fileDraft = null;
      ARC.save();
      ARC.navigate(codeHref(repo, branch, path));
    }

function(ctx) {
      const pr = list('pulls').find((p) => p.id === ctx.id);
      const f = ctx.form || {};
      const user = me();
      if (!user || user.id === pr.authorId) { ARC.closeDialog(); return; }
      const decision = f.decision === 'Approve' ? 'Approve' : (f.decision === 'Request changes' ? 'Request changes' : 'Comment');
      list('reviews').push({ id: uid('rv'), prId: pr.id, commit: pr.compareCommit, reviewerId: user.id, reviewer: user.username, decision: decision, summary: String(f.summary || ''), at: now() });
      ARC.save();
      ARC.closeDialog();
      ARC.render();
    }

function(ctx) {
      const f = ctx.form || {};
      const u = ui();
      const user = me();
      const name = String(f.name || '').trim();
      const ownerLabel = String(f.owner || '');
      const org = list('orgs').find((o) => o.displayName === ownerLabel);
      // A rejected submission keeps what was typed, so the reason can be read and corrected.
      u.repoForm = { owner: ownerLabel, name: String(f.name || ''), description: String(f.description || ''), visibility: f.visibility, readme: !!f.readme };
      if (!name) { u.repoError = 'Repository name is required'; ARC.render(); return; }
      // A repository name identifies the repository in search results and lists, so a name already used
      // anywhere in the system is a conflict and an existing namespace does not free it.
      if (list('repos').some((r) => r.name === name)) { u.repoError = 'Name already exists on this account'; ARC.render(); return; }
      const repo = {
        id: uid('repo'), owner: ownerLabel, ownerType: org ? 'org' : 'user', orgId: org ? org.id : null,
        ownerSlug: org ? org.identifier : ownerLabel, name: name,
        visibility: f.visibility === 'Private' ? 'Private' : 'Public',
        description: String(f.description || ''), defaultBranch: 'main', updated: 'just now', createdBy: user.id, forkOf: null
      };
      list('repos').push(repo);
      list('branches').push({ id: uid('br'), repoId: repo.id, name: 'main', commitId: 'c-' + repo.id + '-1' });
      list('commits').push({ id: 'c-' + repo.id + '-1', repoId: repo.id, branch: 'main', seq: 1, message: 'Initial commit', author: user.username, at: 'just now', parent: null, additions: 1, deletions: 0, files: [] });
      if (f.readme) {
        list('files').push({ id: uid('f'), repoId: repo.id, branch: 'main', path: 'README.md', content: '# ' + name + '\n' });
      }
      u.repoError = '';
      u.repoForm = null;
      ARC.save();
      ARC.navigate(repoBase(repo));
    }

function(ctx) {
      const issue = list('issues').find((i) => i.id === ctx.id);
      const f = ctx.form || {};
      const u = ui();
      const title = String(f.title || '').trim();
      if (!title) { u.editError = 'Title is required'; ARC.render(); return; }
      issue.title = title;
      list('activities').push({ id: uid('ac'), issueId: issue.id, text: ((me() || {}).username || '') + ' edited the title', at: now() });
      u.editingTitle = false;
      u.editError = '';
      ARC.save();
      ARC.render();
    }
